using TownOfHost;
using TownOfHost.Roles.Core;
using AmongUs.GameOptions;
class Program {
 static int passed;
 static readonly CustomRoles[] HamoTargets={CustomRoles.Catalyst,CustomRoles.Conductor,CustomRoles.Trauma,CustomRoles.Surmount,CustomRoles.MemoryRestorer,CustomRoles.Sender,CustomRoles.Fugitive,CustomRoles.Messenger,CustomRoles.ArchVillain,CustomRoles.LonelyWolf,CustomRoles.Clockworker,CustomRoles.Abductor,CustomRoles.MadInvisible,CustomRoles.MadMagic,CustomRoles.MadSender,CustomRoles.Parity,CustomRoles.Lupin,CustomRoles.Daoshi,CustomRoles.Flatfish,CustomRoles.Surviving,CustomRoles.Berserker,CustomRoles.ToughGuy,CustomRoles.Comorbidity,CustomRoles.Murder,CustomRoles.BetrayGuesser,CustomRoles.Experiencer};
 static readonly CustomRoles[] TempTargets={CustomRoles.StepBomber,CustomRoles.Locksmith,CustomRoles.Coroner};
 static readonly CustomRoles[] Targets=HamoTargets.Concat(TempTargets).ToArray();
 static readonly TabGroup[] Tabs={TabGroup.ImpostorRoles,TabGroup.MadmateRoles,TabGroup.CrewmateRoles,TabGroup.NeutralRoles,TabGroup.Combinations,TabGroup.Addons,TabGroup.GhostRoles};
 static void Check(bool ok,string text){if(!ok)throw new Exception(text);}
 static void Test(string name,Action action){Options.Reset();OptionItem.AllOptions.Clear();RoleSettingsDisplay.Reset();BaselineRoleSettingsDisplay.Reset();action();passed++;Console.WriteLine("PASS "+name);}
 static SimpleRoleInfo Info(CustomRoles role,From origin=From.None,CombinationRoles combo=CombinationRoles.None){return SimpleRoleInfo.Create(typeof(RoleBase),p=>new RoleBase(),role,()=>RoleTypes.Crewmate,CustomRoleTypes.Crewmate,800000+(int)role,null,"test",combination:combo,from:origin);}
 static OptionItem Row(CustomRoles role,TabGroup tab=TabGroup.CrewmateRoles,string credit=""){var o=new OptionItem{Id=OptionItem.AllOptions.Count,CustomRole=role,Tab=tab,Name=role.ToString(),Fromtext=credit,Value=37};OptionItem.AllOptions.Add(o);return o;}
 static OptionItem Child(OptionItem parent,CustomRoles owner,string name="Maximum"){var o=new OptionItem{Id=OptionItem.AllOptions.Count,ParentRole=owner,Parent=parent,Tab=parent.Tab,Name=name,Value=11};OptionItem.AllOptions.Add(o);return o;}
 static List<OptionItem> View(TabGroup tab=TabGroup.CrewmateRoles)=>RoleSettingsDisplay.DisplayOptions(tab).ToList();
 static RoleSettingsDisplay.Origin Origin(OptionItem o)=>RoleSettingsDisplay.SectionFor(o.Tab,o);
 static readonly string[] PreferredKeys={"from:TownOfHost_Shell","from:TownOfHost_hamo","from:TownOfHost_Temp","from:TownOfHost_Pko","from:TownOfHost_K","from:TownOfHost_Y"};
 static CustomRoles[] PriorityPool()=>Enum.GetValues<CustomRoles>().Where(role=>!ShellRoleOrigins.HasOverride(role)&&role is not (CustomRoles.NotAssigned or CustomRoles.Snowman or CustomRoles.Android or CustomRoles.Slugger or CustomRoles.DummySpawner or CustomRoles.JackalSeer or CustomRoles.Oblivion or CustomRoles.Moira or CustomRoles.Eater)).ToArray();
 static void SeedSources(TabGroup tab=TabGroup.CrewmateRoles){var roles=PriorityPool();int i=0;foreach(var from in Enum.GetValues<From>().Reverse()){Info(roles[i],from);Row(roles[i++],tab);}}
 static List<OptionItem> BaselineView(TabGroup tab=TabGroup.CrewmateRoles)=>BaselineRoleSettingsDisplay.DisplayOptions(tab).ToList();
 static void ModBoth(){RoleSettingsDisplay.Toggle();BaselineRoleSettingsDisplay.Toggle();}
 static void Main(){
 Test("default is gojuon and button targets MOD order",()=>Check(RoleSettingsDisplay.CurrentMode==RoleSettingsDisplay.Mode.Gojuon&&RoleSettingsDisplay.TargetButtonText=="MOD順\nにする","default"));
 Test("gojuon to MOD to gojuon changes destination labels",()=>{RoleSettingsDisplay.Toggle();Check(RoleSettingsDisplay.CurrentMode==RoleSettingsDisplay.Mode.Mod&&RoleSettingsDisplay.TargetButtonText=="あいうえお\n順にする"&&RoleSettingsDisplay.TargetName=="あいうえお順","mode2");RoleSettingsDisplay.Toggle();Check(RoleSettingsDisplay.CurrentMode==RoleSettingsDisplay.Mode.Gojuon&&RoleSettingsDisplay.TargetButtonText=="MOD順\nにする"&&RoleSettingsDisplay.TargetName=="MOD順","mode1");});
 Test("only seven role-list tabs support the toggle",()=>{foreach(var tab in Enum.GetValues<TabGroup>())Check(RoleSettingsDisplay.IsRoleList(tab)==Tabs.Contains(tab),"tab "+tab);});
 Test("all factions addon ghost and combo lists can switch",()=>{foreach(var tab in Tabs){OptionItem.AllOptions.Clear();RoleSettingsDisplay.Reset();var p=Row(CustomRoles.Prankster,tab);var c=Row(CustomRoles.Chief,tab);Check(View(tab).SequenceEqual(new[]{c,p}),"gojuon "+tab);RoleSettingsDisplay.Toggle();Check(View(tab).Count==2,"mod "+tab);RoleSettingsDisplay.Toggle();Check(View(tab).SequenceEqual(new[]{c,p}),"roundtrip "+tab);}});
 Test("Japanese readings put kanji names in reading order",()=>{var p=Row(CustomRoles.Prankster);var m=Row(CustomRoles.MemoryRestorer);var c=Row(CustomRoles.Chief);Check(View().SequenceEqual(new[]{m,c,p}),"kanji reading");});
 Test("kana width small kana voicing and long marks normalize",()=>Check(RoleSettingsReadings.Normalize("<b>ﾌﾟﾗﾝｸｽﾀｰ</b>")==RoleSettingsReadings.Normalize("ぷらんくすたー"),"normalization"));
 Test("26 requested sources retain hamo",()=>{foreach(var role in HamoTargets){var origin=RoleSettingsDisplay.OriginFor(role);Check(origin.Name=="TownOfHost-hamo"&&origin.Key=="from:TownOfHost_hamo","source "+role);}});
 Test("existing Shell and third-party sources survive",()=>{Info(CustomRoles.Prankster,From.TownOfHost_Shell);Info(CustomRoles.Destroyer,From.NebulaontheShip);Check(RoleSettingsDisplay.OriginFor(CustomRoles.Prankster).Key=="from:TownOfHost_Shell","Shell");Check(RoleSettingsDisplay.OriginFor(CustomRoles.Destroyer).Key=="from:NebulaontheShip","Nebula");});
 Test("new typed sources appear without changing planner tables",()=>{Info(CustomRoles.Sheriff,From.ExtremeRoles);var o=Row(CustomRoles.Sheriff);Check(Origin(o).Name=="ExtremeRoles","automatic source");});
 Test("explicit addon literal credits use existing source aliases",()=>{var a=Row(CustomRoles.Guesser,TabGroup.Addons,"<color=#fff>From:</color>The Other Roles");Info(CustomRoles.Sheriff,From.TheOtherRoles);var b=Row(CustomRoles.Sheriff,TabGroup.Addons);Check(Origin(a).Key==Origin(b).Key,"literal alias");});
 Test("underscore and hyphen hamo credits form one source",()=>{var a=Row(CustomRoles.Symbol,TabGroup.Addons,"From:TownOfHost_hamo");var b=Row(CustomRoles.Berserker,TabGroup.Addons);Check(Origin(a).Key==Origin(b).Key&&Origin(a).Name=="TownOfHost-hamo","hamo alias");});
 Test("custom explicit credit stays explicit",()=>{var a=Row(CustomRoles.Sheriff,credit:"<b>From:</b>My Custom Mod");Check(Origin(a).Name=="My Custom Mod"&&!Origin(a).Unset,"literal");});
 Test("no source is inferred from name or faction",()=>{var o=Row(CustomRoles.Sheriff);Check(Origin(o).Unset&&Origin(o).Name=="出典未設定","unknown");});
 Test("unknown source group is kept after known groups",()=>{var unknown=Row(CustomRoles.Sheriff);var known=Row(CustomRoles.Berserker);RoleSettingsDisplay.Toggle();Check(View().Last()==unknown&&View().Contains(known),"unknown group");});
 Test("MOD groups are contiguous and sorted within by reading",()=>{Info(CustomRoles.Prankster,From.TownOfHost_Shell);Info(CustomRoles.Chief,From.TownOfHost_Shell);Row(CustomRoles.Prankster);Row(CustomRoles.MemoryRestorer);Row(CustomRoles.Chief);Row(CustomRoles.Abductor);RoleSettingsDisplay.Toggle();var list=View();var keys=list.Select(o=>Origin(o).Key).ToList();Check(keys.Distinct().Count()==2,"group count");foreach(var key in keys.Distinct()){var indexes=list.Select((o,i)=>(o,i)).Where(x=>Origin(x.o).Key==key).Select(x=>x.i).ToArray();Check(indexes.Last()-indexes.First()+1==indexes.Length,"split source");var roles=list.Where(o=>Origin(o).Key==key).Select(o=>RoleSettingsReadings.Key(o.CustomRole)).ToList();Check(roles.SequenceEqual(roles.OrderBy(x=>x,StringComparer.Ordinal)),"source reading");}});
 Test("26 roles share one hamo group without duplicates",()=>{foreach(var role in HamoTargets)Row(role);RoleSettingsDisplay.Toggle();var view=View();Check(view.Count==26&&view.Distinct().Count()==26&&view.Select(o=>Origin(o).Key).Distinct().Count()==1,"hamo members");});
 Test("maximum and nested settings stay with root role",()=>{var p=Row(CustomRoles.Prankster);var max=Child(p,CustomRoles.Prankster);var nested=Child(max,CustomRoles.Prankster,"Nested");var a=Row(CustomRoles.Abductor);foreach(var mode in new[]{0,1}){var list=View();var i=list.IndexOf(p);Check(list[i+1]==max&&list[i+2]==nested,"split block");Check(Origin(p).Key==Origin(nested).Key,"child source");RoleSettingsDisplay.Toggle();}});
 Test("pair child cannot be misclassified by its own ParentRole",()=>{Info(CustomRoles.Trauma,combo:CombinationRoles.TraumaandSurmount);Info(CustomRoles.Surmount,combo:CombinationRoles.TraumaandSurmount);var t=Row(CustomRoles.Trauma,TabGroup.Combinations);var child=Child(t,CustomRoles.Surmount,"PartnerSetting");Check(RoleSettingsDisplay.RootRole(child)==CustomRoles.Trauma,"pair root");Check(Origin(t).Key==Origin(child).Key&&Origin(t).Name=="TownOfHost-hamo","pair origin");});
 Test("mixed source combination is explicit and never assigned one source",()=>{Info(CustomRoles.Chief,From.TownOfHost_Shell,CombinationRoles.TraumaandSurmount);Info(CustomRoles.Sheriff,From.TheOtherRoles,CombinationRoles.TraumaandSurmount);var p=Row(CustomRoles.Chief,TabGroup.Combinations);var origin=Origin(p);Check(origin.Key.StartsWith("mixed:")&&origin.Name.Contains("TownOfHost_Shell")&&origin.Name.Contains("TheOtherRoles"),"mixed pair");});
 Test("combination with unknown partner keeps unknown label",()=>{Info(CustomRoles.Chief,From.TownOfHost_Shell,CombinationRoles.TraumaandSurmount);Info(CustomRoles.Sheriff,From.None,CombinationRoles.TraumaandSurmount);var p=Row(CustomRoles.Chief,TabGroup.Combinations);Check(Origin(p).Name.Contains("出典未設定"),"inferred partner");});
 Test("common settings remain trailing and retain order",()=>{var shared=Row(CustomRoles.NotAssigned);var c=Row(CustomRoles.Chief);var more=Row(CustomRoles.NotAssigned);foreach(var mode in new[]{0,1}){Check(View().SequenceEqual(new[]{c,shared,more}),"common settings");RoleSettingsDisplay.Toggle();}});
 Test("non-role pages keep exact order in both modes",()=>{foreach(var tab in new[]{TabGroup.MainSettings,TabGroup.Game,TabGroup.Other,TabGroup.Other2}){OptionItem.AllOptions.Clear();var p=Row(CustomRoles.Prankster,tab);var c=Row(CustomRoles.Chief,tab);Check(View(tab).SequenceEqual(new[]{p,c}),"general order");RoleSettingsDisplay.Toggle();Check(View(tab).SequenceEqual(new[]{p,c}),"mod general order");}});
 Test("100 switches retain values IDs names parents and reference identity",()=>{var p=Row(CustomRoles.Prankster);Child(p,CustomRoles.Prankster);Row(CustomRoles.MemoryRestorer);Row(CustomRoles.NotAssigned);var original=OptionItem.AllOptions.ToArray();var before=original.Select(o=>(o.Id,o.Value,o.Name,o.Parent,o.CustomRole,o.ParentRole)).ToArray();for(int i=0;i<100;i++){RoleSettingsDisplay.Toggle();var list=View();Check(list.Count==original.Length&&list.Distinct().Count()==original.Length&&list.All(original.Contains),"missing duplicate");Check(OptionItem.AllOptions.SequenceEqual(original),"global ordering changed");Check(before.SequenceEqual(original.Select(o=>(o.Id,o.Value,o.Name,o.Parent,o.CustomRole,o.ParentRole))),"mutated setting");}});
 Test("planner cannot invent retired or unregistered roles",()=>{Row(CustomRoles.Prankster);Row(CustomRoles.Chief);foreach(var mode in new[]{0,1}){Check(View().All(o=>o.CustomRole is CustomRoles.Prankster or CustomRoles.Chief),"invented role");RoleSettingsDisplay.Toggle();}});
 Test("cache invalidates after option registration count changes",()=>{Row(CustomRoles.Prankster);Check(View().Count==1,"initial");var c=Row(CustomRoles.Chief);Check(View().Count==2&&View().First()==c,"stale plan");});
 Test("only the obsolete decorative group header is suppressed",()=>{var legacy=new ObjectOptionitem{Name="Group-Addon",IsHedderObject=true};var normal=new ObjectOptionitem{Name="Role Option",IsHedderObject=true};Check(RoleSettingsDisplay.IsLegacyGroupHeader(legacy)&&!RoleSettingsDisplay.IsLegacyGroupHeader(normal)&&!RoleSettingsDisplay.IsLegacyGroupHeader(new OptionItem{Name="Group-Addon"}),"legacy header scope");});
 Test("opening a new menu resets to mode 1",()=>{Row(CustomRoles.Prankster);RoleSettingsDisplay.Toggle();View();RoleSettingsDisplay.Reset();Check(RoleSettingsDisplay.TargetButtonText=="MOD順\nにする"&&View().Count==1,"menu reset");});
 Test("same sort keys retain existing relative order",()=>{var one=Row(CustomRoles.Sheriff);var two=Row(CustomRoles.Sheriff);Check(View().SequenceEqual(new[]{one,two}),"stable tie");});
 Test("Shell hamo Temp then previous priority groups lead in the requested order on every role tab",()=>{foreach(var tab in Tabs){Options.Reset();OptionItem.AllOptions.Clear();RoleSettingsDisplay.Reset();BaselineRoleSettingsDisplay.Reset();SeedSources(tab);ModBoth();var keys=View(tab).Select(o=>Origin(o).Key).Distinct().ToArray();Check(keys.Take(6).SequenceEqual(PreferredKeys),"priority "+tab);}});
 Test("all other source rows retain their exact previous relative order",()=>{SeedSources();ModBoth();var old=BaselineView().Where(o=>!PreferredKeys.Contains(Origin(o).Key)).ToArray();var now=View().Where(o=>!PreferredKeys.Contains(Origin(o).Key)).ToArray();Check(now.SequenceEqual(old),"other MOD order changed");});
 Test("all groups retain the previous within-group reading order",()=>{var pool=PriorityPool();int i=0;foreach(var from in new[]{From.TownOfHost_Shell,From.TownOfHost_hamo,From.TownOfHost_Pko,From.TownOfHost_K,From.TownOfHost_Y,From.ExtremeRoles,From.None}){Info(pool[i],from);Row(pool[i++]);Info(pool[i],from);Row(pool[i++]);}ModBoth();var old=BaselineView();var now=View();foreach(var key in now.Select(o=>Origin(o).Key).Distinct())Check(now.Where(o=>Origin(o).Key==key).SequenceEqual(old.Where(o=>Origin(o).Key==key)),"inner reading order "+key);});
 Test("gojuon mode exactly matches the pre-change planner before and after toggling",()=>{SeedSources();var parent=OptionItem.AllOptions[0];Child(parent,parent.CustomRole);Row(CustomRoles.NotAssigned);Check(View().SequenceEqual(BaselineView()),"initial gojuon changed");ModBoth();View();BaselineView();ModBoth();Check(View().SequenceEqual(BaselineView()),"return gojuon changed");});
 Test("canonical hyphen underscore and space source aliases get priorities",()=>{var pool=PriorityPool();var credits=new[]{"TownOfHost-Y","TownOfHost_K","TownOfHost Pko","TownOfHost-Temp","TownOfHost_hamo","TownOfHost-Shell"};for(int i=0;i<credits.Length;i++)Row(pool[i],credit:"From:"+credits[i]);ModBoth();Check(View().Select(o=>Origin(o).Key).SequenceEqual(PreferredKeys),"source aliases");});
 Test("existing source labels remain exact and other MODs stay independent",()=>{SeedSources();ModBoth();var old=BaselineView();var current=View();Check(current.Select(o=>Origin(o).Key).Distinct().Count()==Enum.GetValues<From>().Length,"merged sources");foreach(var o in current){var before=BaselineRoleSettingsDisplay.SectionFor(o.Tab,o);Check(before.Key==Origin(o).Key&&before.Name==Origin(o).Name,"source renamed");}Check(current.All(o=>Origin(o).Name!="その他のMOD"),"catch-all group invented");});
 Test("absent preferred groups do not create rows or headers",()=>{Info(CustomRoles.Sheriff,From.ExtremeRoles);var only=Row(CustomRoles.Sheriff);ModBoth();Check(View().SequenceEqual(new[]{only})&&!PreferredKeys.Contains(Origin(only).Key),"empty preferred groups");});
 Test("mixed source combinations remain independent and keep their block",()=>{Info(CustomRoles.Chief,From.TownOfHost_Shell,CombinationRoles.TraumaandSurmount);Info(CustomRoles.Sheriff,From.TheOtherRoles,CombinationRoles.TraumaandSurmount);Info(CustomRoles.Prankster,From.TownOfHost_Shell);var mixed=Row(CustomRoles.Chief,TabGroup.Combinations);var child=Child(mixed,CustomRoles.Sheriff,"Partner");var shell=Row(CustomRoles.Prankster,TabGroup.Combinations);ModBoth();var view=View(TabGroup.Combinations);Check(view.SequenceEqual(new[]{shell,mixed,child}),"mixed block order");var origin=Origin(mixed);var old=BaselineRoleSettingsDisplay.SectionFor(mixed.Tab,mixed);Check(origin.Key.StartsWith("mixed:")&&origin.Key==old.Key&&origin.Name==old.Name,"mixed source changed");});
 Test("unknown sources remain trailing with their previous rows and labels",()=>{SeedSources();ModBoth();var old=BaselineView().Where(o=>Origin(o).Unset).ToArray();var current=View();Check(current.Where(o=>Origin(o).Unset).SequenceEqual(old)&&current.Last()==old.Last(),"unknown handling changed");});
 Test("header collapse changes no options or values",()=>{var p=Row(CustomRoles.Prankster);var m=Child(p,p.CustomRole);var before=View().ToArray();var header=RoleSettingsDisplay.HeaderFor(p.Tab,p);RoleSettingsDisplay.ToggleHeader(p.Tab,header);Check(RoleSettingsDisplay.IsCollapsed(p.Tab,header),"not collapsed");Check(View().SequenceEqual(before)&&p.Value==37&&m.Value==11,"data changed");});
 Test("nested maximum uses the same collapsible header",()=>{var p=Row(CustomRoles.Experiencer);var m=Child(p,p.CustomRole);RoleSettingsDisplay.SetAllCollapsed(p.Tab,true);Check(RoleSettingsDisplay.IsCollapsed(p.Tab,RoleSettingsDisplay.HeaderFor(p.Tab,p))&&RoleSettingsDisplay.IsCollapsed(p.Tab,RoleSettingsDisplay.HeaderFor(m.Tab,m)),"split block");});
 Test("all open and all close roundtrip on every role tab",()=>{foreach(var tab in Tabs){Row(CustomRoles.Experiencer,tab);RoleSettingsDisplay.SetAllCollapsed(tab,true);Check(RoleSettingsDisplay.AnyCollapsed(tab),"close "+tab);RoleSettingsDisplay.SetAllCollapsed(tab,false);Check(!RoleSettingsDisplay.AnyCollapsed(tab),"open "+tab);}});
 Test("collapse state is independent across modes",()=>{var p=Row(CustomRoles.Prankster);RoleSettingsDisplay.SetAllCollapsed(p.Tab,true);RoleSettingsDisplay.Toggle();Check(!RoleSettingsDisplay.AnyCollapsed(p.Tab),"mode leak");RoleSettingsDisplay.Toggle();Check(RoleSettingsDisplay.AnyCollapsed(p.Tab),"lost state");});
 Test("collapse state is independent across tabs",()=>{var p=Row(CustomRoles.Prankster);var q=Row(CustomRoles.Prankster,TabGroup.NeutralRoles);RoleSettingsDisplay.SetAllCollapsed(p.Tab,true);Check(!RoleSettingsDisplay.AnyCollapsed(q.Tab),"tab leak");});
 Test("reset reopens headers",()=>{var p=Row(CustomRoles.Experiencer);RoleSettingsDisplay.SetAllCollapsed(p.Tab,true);RoleSettingsDisplay.Reset();Check(!RoleSettingsDisplay.AnyCollapsed(p.Tab),"stale collapse");});
 Test("shared settings never disappear in a collapsed section",()=>{var p=Row(CustomRoles.Prankster);var shared=Row(CustomRoles.NotAssigned);RoleSettingsDisplay.SetAllCollapsed(p.Tab,true);Check(RoleSettingsDisplay.HeaderFor(shared.Tab,shared)==null&&View().Contains(shared),"shared hidden");});
 Test("new Experiencer source and reading are explicit",()=>{var p=Row(CustomRoles.Experiencer,TabGroup.ImpostorRoles);Check(RoleSettingsDisplay.OriginFor(p.CustomRole).Key=="from:TownOfHost_hamo","from");Check(RoleSettingsReadings.Key(p.CustomRole).StartsWith("えくす"),"reading");});
 Test("all close respects MOD sources and combinations",()=>{var p=Row(CustomRoles.Prankster);var e=Row(CustomRoles.Experiencer);RoleSettingsDisplay.Toggle();RoleSettingsDisplay.SetAllCollapsed(p.Tab,true);Check(RoleSettingsDisplay.IsCollapsed(p.Tab,RoleSettingsDisplay.HeaderFor(p.Tab,p))&&RoleSettingsDisplay.IsCollapsed(e.Tab,RoleSettingsDisplay.HeaderFor(e.Tab,e)),"source collapse");RoleSettingsDisplay.SetAllCollapsed(p.Tab,false);Check(View().Count==2&&!RoleSettingsDisplay.AnyCollapsed(p.Tab),"lost rows");});
 Test("three Temp roles form a separate group after hamo",()=>{foreach(var r in Targets)Row(r);Info(CustomRoles.Prankster,From.TownOfHost_Shell);Row(CustomRoles.Prankster);RoleSettingsDisplay.Toggle();var view=View();Check(view.Count==30&&view.Distinct().Count()==30,"missing duplicate");Check(view.Select(o=>Origin(o).Key).Distinct().SequenceEqual(new[]{"from:TownOfHost_Shell","from:TownOfHost_hamo","from:TownOfHost_Temp"}),"leading order");Check(view.Where(o=>Origin(o).Key=="from:TownOfHost_Temp").Select(o=>o.CustomRole).ToHashSet().SetEquals(TempTargets),"Temp members");foreach(var r in TempTargets)Check(RoleSettingsDisplay.OriginFor(r).Name=="TownOfHost_Temp","Temp name");});
 Test("Temp collapse and reopening keeps children values and other groups",()=>{var t=Row(CustomRoles.StepBomber);var child=Child(t,t.CustomRole);var h=Row(CustomRoles.Experiencer);RoleSettingsDisplay.Toggle();var header=RoleSettingsDisplay.HeaderFor(t.Tab,t);var before=View().ToArray();RoleSettingsDisplay.ToggleHeader(t.Tab,header);Check(RoleSettingsDisplay.IsCollapsed(t.Tab,header)&&RoleSettingsDisplay.IsCollapsed(t.Tab,RoleSettingsDisplay.HeaderFor(child.Tab,child)),"Temp not collapsed");Check(!RoleSettingsDisplay.IsCollapsed(h.Tab,RoleSettingsDisplay.HeaderFor(h.Tab,h)),"hamo also collapsed");RoleSettingsDisplay.ToggleHeader(t.Tab,header);Check(!RoleSettingsDisplay.IsCollapsed(t.Tab,header)&&View().SequenceEqual(before)&&t.Value==37&&child.Value==11,"lost data");});
 Test("Temp aliases join same independent typed group",()=>{var a=Row(CustomRoles.Sheriff,credit:"From:TownOfHost_Temp");var b=Row(CustomRoles.StepBomber);Check(Origin(a).Key==Origin(b).Key&&Origin(a).Name=="TownOfHost_Temp","Temp alias");});
 Test("Damocles belongs to Shell and precedes previous new impostor in both modes",()=>{Info(CustomRoles.Damocles,From.TownOfHost_Shell);var d=Row(CustomRoles.Damocles,TabGroup.ImpostorRoles);var previous=Row(CustomRoles.StepBomber,TabGroup.ImpostorRoles);var child=Child(d,d.CustomRole);var original=OptionItem.AllOptions.Select(o=>(o.Id,o.Value,o.Parent)).ToArray();for(int n=0;n<2;n++){var view=View(TabGroup.ImpostorRoles);Check(view.IndexOf(d)<view.IndexOf(previous)&&view.IndexOf(child)==view.IndexOf(d)+1,"new role ordering");Check(Origin(d).Key=="from:TownOfHost_Shell"&&Origin(d).Name=="TownOfHost_Shell","Shell origin");Check(original.SequenceEqual(OptionItem.AllOptions.Select(o=>(o.Id,o.Value,o.Parent))),"settings changed");RoleSettingsDisplay.Toggle();}});
 Test("Idol uses Shell source and reading before prior new roles without changing settings",()=>{Info(CustomRoles.Idol,From.TownOfHost_Shell);var idol=Row(CustomRoles.Idol,TabGroup.CrewmateRoles);var coroner=Row(CustomRoles.Coroner,TabGroup.CrewmateRoles);var child=Child(idol,CustomRoles.Idol);Check(string.CompareOrdinal(RoleSettingsReadings.Key(CustomRoles.Idol),RoleSettingsReadings.Key(CustomRoles.Damocles))<0,"new role order");for(int n=0;n<2;n++){var view=View(TabGroup.CrewmateRoles);Check(view.IndexOf(idol)<view.IndexOf(coroner)&&view.IndexOf(child)==view.IndexOf(idol)+1&&Origin(idol).Key=="from:TownOfHost_Shell"&&idol.Value==37&&child.Value==11,"Idol group/order/values");RoleSettingsDisplay.Toggle();}});
 Console.WriteLine($"RESULT {passed} passed, 0 failed");
 }
}
